    if not cwd.startswith('/'):
        return None

    # Normalize cwd (should already be canonical)
    if cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative
    if not path.startswith('/'):
        current = cwd
    else:
        current = ''

