                    link_dir = candidate.rsplit('/', 1)[0]
                    if link_dir == '':
                        link_dir = '/'

                # Combine link_dir with target
                if link_dir == '/':
                    target = '/' + target
                else:
                    target = link_dir + '/' + target

            # Now resolve target as if it were the current path
            # We need to restart resolution from target with remaining components
            target_components = target.split('/')
            components = target_components + remaining
            current = ''
            i = 0
            continue

        current = candidate
        i += 1

    # Ensure current is canonical (no trailing slash except for '/')
    if current == '':
        current = '/'
    elif current.endswith('/') and current != '/':
        current = current.rstrip('/')

    return current

